 readonly Button check=new(){Text="ตรวจความพร้อม (ไม่เชื่อมต่อ)"},startRead=new(){Text="อนุญาตอ่านทุก5วินาที"},stopRead=new(){Text="หยุดอ่าน"},startSend=new(){Text="อนุญาตส่ง Gateway"},stopSend=new(){Text="หยุดส่ง"},export=new(){Text="ส่งออกคิว CSV ใน AQUA"};
 readonly Label readiness=new(){Text="ยังไม่ตรวจ — ไม่มีการเชื่อมต่อ WinCC",AutoSize=true},captureStatus=new(){Text="READ:หยุดรออนุญาต",AutoSize=true},deliveryStatus=new(){Text="SEND:หยุดรออนุญาต",AutoSize=true},counts=new(){Text="ยังไม่เปิดคิว — ไม่เริ่มงานอัตโนมัติ",AutoSize=true},storage=new(){Text="ที่เก็บ:AQUA user profile;สร้างเมื่ออนุญาตเท่านั้น",AutoSize=true};
 readonly DataGridView values=new(){ReadOnly=true,AllowUserToAddRows=false,AllowUserToDeleteRows=false,RowHeadersVisible=false,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill,Dock=DockStyle.Fill,BackgroundColor=Color.FromArgb(15,27,40)};
 readonly List<Control> configControls=[];CancellationTokenSource? readCts,sendCts;Task? readTask,sendTask;WorkerSession? worker;DurableSpool? spool;string? profile;bool closing,allowClose;
 public ReaderWindow(){
  Text="AQUA COMMAND • WinCC Runtime Reader0.9 • READ ONLY";Width=1220;Height=900;MinimumSize=new(1040,760);StartPosition=FormStartPosition.CenterScreen;Font=new("Segoe UI",10);BackColor=Color.FromArgb(11,20,32);ForeColor=Color.FromArgb(235,242,247);
  var layout=new TableLayoutPanel{Dock=DockStyle.Fill,Padding=new(22),ColumnCount=1,RowCount=8};layout.RowStyles.Add(new(SizeType.AutoSize));layout.RowStyles.Add(new(SizeType.AutoSize));layout.RowStyles.Add(new(SizeType.AutoSize));layout.RowStyles.Add(new(SizeType.AutoSize));layout.RowStyles.Add(new(SizeType.AutoSize));layout.RowStyles.Add(new(SizeType.AutoSize));layout.RowStyles.Add(new(SizeType.Percent,100));layout.RowStyles.Add(new(SizeType.AutoSize));Controls.Add(layout);
  layout.Controls.Add(new Label{Text="AQUA COMMAND   /   LOCAL WINCC RUNTIME READER",AutoSize=true,Font=new("Segoe UI",17,FontStyle.Bold),Padding=new(0,0,0,10)});
  layout.Controls.Add(new Label{Text="อ่านเฉพาะ Tag ที่เลือกผ่าน OPCServer.WinCC บน Windows เครื่องนี้ ไม่มีข้อมูลจำลอง ไม่มีคำสั่งเขียน PLC/WinCC\nReadiness=อ่าน registryเท่านั้น · Capture=อาจเริ่ม COM server ที่ติดตั้งไว้ · Send=HTTPS ไป Gateway ที่ระบุ",AutoSize=true,Padding=new(0,0,0,12),ForeColor=Color.LightSteelBlue});
  var grid=new TableLayoutPanel{ColumnCount=2,AutoSize=true,Dock=DockStyle.Top};grid.ColumnStyles.Add(new(SizeType.Absolute,220));grid.ColumnStyles.Add(new(SizeType.Percent,100));identity.Items.AddRange(["PC-01","PC-02","PC-03"]);identity.SelectedIndex=0;
  Add(grid,"Exporter identity",identity);Add(grid,"Selected binary Tag names",tags);Add(grid,"Gateway URL",gateway);Add(grid,"Enrollment key",secret);var certRow=new TableLayoutPanel{ColumnCount=3,AutoSize=true,Dock=DockStyle.Top};certRow.ColumnStyles.Add(new(SizeType.Percent,100));certRow.ColumnStyles.Add(new(SizeType.AutoSize));certRow.ColumnStyles.Add(new(SizeType.AutoSize));certRow.Controls.Add(ca);var pick=new Button{Text="เลือก CA certificate",AutoSize=true};pick.Click+=(_,_)=>{using var dialog=new OpenFileDialog{Filter="CA certificate|*.crt;*.cer;*.pem|All files|*.*"};if(dialog.ShowDialog(this)==DialogResult.OK)ca.Text=dialog.FileName;};certRow.Controls.Add(pick);var clear=new Button{Text="Windows trust",AutoSize=true};clear.Click+=(_,_)=>ca.Text="";certRow.Controls.Add(clear);Add(grid,"Gateway certificate trust",certRow);configControls.AddRange([identity,tags,gateway,secret,pick,clear,mapping,organizational]);layout.Controls.Add(grid);
  var consent=new FlowLayoutPanel{AutoSize=true,Dock=DockStyle.Top,FlowDirection=FlowDirection.TopDown};consent.Controls.Add(organizational);consent.Controls.Add(mapping);layout.Controls.Add(consent);
  var buttons=new FlowLayoutPanel{AutoSize=true,Dock=DockStyle.Top,Padding=new(0,10,0,8)};foreach(var b in new[]{check,startRead,stopRead,startSend,stopSend,export}){b.AutoSize=true;b.Padding=new(7);buttons.Controls.Add(b);}layout.Controls.Add(buttons);
  var status=new FlowLayoutPanel{AutoSize=true,Dock=DockStyle.Top,FlowDirection=FlowDirection.TopDown};foreach(var l in new[]{readiness,captureStatus,deliveryStatus,counts,storage})status.Controls.Add(l);layout.Controls.Add(status);
  foreach(var name in new[]{"Tag","RAW","State","Quality/code","HRESULT","Source timestamp(UTC)","Read completed(UTC)"})values.Columns.Add(name,name);values.DefaultCellStyle.BackColor=Color.FromArgb(18,34,50);values.DefaultCellStyle.ForeColor=ForeColor;values.ColumnHeadersDefaultCellStyle.BackColor=Color.FromArgb(26,48,68);values.ColumnHeadersDefaultCellStyle.ForeColor=ForeColor;values.EnableHeadersVisualStyles=false;values.AutoSizeRowsMode=DataGridViewAutoSizeRowsMode.AllCells;layout.Controls.Add(values);
  layout.Controls.Add(new Label{Text="Gateway ACK=durable local receipt ไม่ใช่ Internet/Telegram delivery · เปลี่ยน Tagยังคงคิวและsequenceเดิม แยกโปรไฟล์เมื่อเปลี่ยนidentity · CSVส่งออกเฉพาะpendingที่ยังไม่ACK",AutoSize=true,ForeColor=Color.LightSteelBlue,Padding=new(0,10,0,0)});
  check.Click+=(_,_)=>Inspect();startRead.Click+=async(_,_)=>await BeginRead();stopRead.Click+=async(_,_)=>await StopRead();startSend.Click+=async(_,_)=>await BeginSend();stopSend.Click+=async(_,_)=>await StopSend();export.Click+=(_,_)=>Export();FormClosing+=OnClosing;Style(this);Sync();
