 static void Style(Control parent){foreach(Control c in parent.Controls){if(c is TextBoxBase||c is ComboBox){c.BackColor=Color.FromArgb(18,34,50);c.ForeColor=Color.FromArgb(235,242,247);}if(c is Button b){b.FlatStyle=FlatStyle.Flat;b.FlatAppearance.BorderColor=Color.FromArgb(49,79,101);b.BackColor=Color.FromArgb(26,48,68);b.ForeColor=Color.FromArgb(235,242,247);b.UseVisualStyleBackColor=false;}Style(c);}}
 static void Add(TableLayoutPanel grid,string title,Control control){var row=grid.RowCount++;grid.RowStyles.Add(new(SizeType.AutoSize));grid.Controls.Add(new Label{Text=title,AutoSize=true,Padding=new(0,8,10,8)},0,row);control.Dock=DockStyle.Fill;control.Margin=new(0,4,0,4);grid.Controls.Add(control,1,row);}
 ReaderConfig Config()=>new(){SourceId=identity.Text,Tags=tags.Text.Split(['\r','\n'],StringSplitOptions.TrimEntries|StringSplitOptions.RemoveEmptyEntries).ToList(),MappingConfirmed=mapping.Checked,GatewayUrl=gateway.Text.Trim(),Secret=secret.Text.Trim(),CaFile=ca.Text};
 void Inspect(){try{var r=Readiness.Inspect();readiness.Text=$"REGISTERED:{ReaderConfig.ProgId} • {r.View} • {r.Clsid}\n{r.Executable}\nการลงทะเบียนไม่ยืนยันว่า Runtimeพร้อมหรือได้รับอนุญาต ไม่มีการเชื่อมต่อ";}catch(Exception e){readiness.Text=e.Message;}}
 void EnsureStore(ReaderConfig config){var wanted=config.ProfileId();if(spool is not null&&profile==wanted)return;spool?.Dispose();spool=null;profile=null;var dir=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"AquaCommand","WinCCReader","profiles",wanted);spool=new DurableSpool(dir,wanted);profile=wanted;storage.Text="AQUA spool:"+dir;UpdateCounts();}
 bool Confirm(string title,string text)=>MessageBox.Show(this,text,title,MessageBoxButtons.OKCancel,MessageBoxIcon.Warning,MessageBoxDefaultButton.Button2)==DialogResult.OK;
 async Task BeginRead(){
  if(readCts is not null||closing)return;
  ReaderConfig config;try{config=Config();config.ValidateCapture();if(!organizational.Checked)throw new InvalidOperationException("ต้องได้รับอนุญาตจากหน่วยงานก่อนอ่าน Runtime โปรดตรวจช่องยืนยัน");var r=Readiness.Inspect();if(!Confirm("อนุญาตอ่าน Runtime ของเครื่องนี้",$"Local server:{ReaderConfig.ProgId}\nCLSID:{r.Clsid}\nRegistered executable:{r.Executable}\n\nTags({config.Tags.Count}):{string.Join(", ",config.Tags.Take(12))}{(config.Tags.Count>12?" …":"")}\nอ่านทุก5วินาทีจนกดหยุด ไม่ถามซ้ำระหว่าง session\n\nCOM connectionอาจเริ่ม serverที่ติดตั้งไว้ ไม่แก้WinCC/DCOM/บริการ ไม่มีคำสั่งเขียน ค่าbinaryต้องตรวจmappingเอง\nสร้างคิวเฉพาะ AQUA profile ส่งข้อมูลยังไม่อนุญาต\n\nยืนยันสิทธิ์อ่านและเริ่ม?"))return;EnsureStore(config);}catch(Exception e){Error(e);return;}
  readCts=new();var token=readCts.Token;Sync();values.Rows.Clear();readTask=CaptureLoop(config,token);await readTask;
 }
 async Task CaptureLoop(ReaderConfig config,CancellationToken token){
  try{captureStatus.Text="READ:กำลังเชื่อมต่อ local OPC DA หลังอนุญาต";using var owned=new WorkerSession();worker=owned;await owned.StartAsync(config,token);var schedule=Stopwatch.StartNew();long next=0;
   while(true){token.ThrowIfCancellationRequested();var frame=await owned.ReadAsync(token);token.ThrowIfCancellationRequested();spool!.Append(config,frame);ShowFrame(config,frame);UpdateCounts();captureStatus.Text="READ:อ่านจริงและเก็บแล้ว "+frame.ReadAt+" • รอบ5วินาที";do{next+=5000;}while(next<=schedule.ElapsedMilliseconds);var delay=next-schedule.ElapsedMilliseconds;await Task.Delay(TimeSpan.FromMilliseconds(delay),token);}
  }catch(OperationCanceledException){captureStatus.Text="READ:หยุดแล้ว • ค่าบนหน้าจอเป็น CACHED";}catch(Exception e){captureStatus.Text="READ:หยุดเพราะผิดพลาด • ค่าบนหน้าจอเป็น CACHED";Error(e);}finally{worker=null;readCts?.Dispose();readCts=null;Sync();}
 }
 async Task StopRead(){readCts?.Cancel();worker?.Stop();if(readTask is not null)await readTask;}
 async Task BeginSend(){
  if(sendCts is not null||closing)return;ReaderConfig config;try{config=Config();config.ValidateCapture();config.ValidateTransfer();if(!Confirm("อนุญาตส่งข้อมูลจากคิว",$"Exporter:{config.SourceId}\nGateway:{config.GatewayUrl}\nTrust:{(config.CaFile.Length==0?"Windows trust store":config.CaFile)}\n\nส่งคิวค้างและข้อมูลใหม่ผ่านHTTPS+HMACจนกดหยุด\nGateway ACKยืนยันว่ารับเก็บแล้ว ไม่ใช่Telegramสำเร็จ\nไม่สแกนเครือข่าย ไม่เปิดInternet sharing\n\nยืนยันปลายทางและอนุญาตส่ง?"))return;EnsureStore(config);}catch(Exception e){Error(e);return;}
  sendCts=new();var token=sendCts.Token;Sync();sendTask=Transfer(config,token);await sendTask;
 }
 async Task Transfer(ReaderConfig config,CancellationToken token){
  try{using var sender=new AquaSender(config);var failures=0;while(true){token.ThrowIfCancellationRequested();try{var sent=await sender.SendBatchAsync(spool!,token);failures=0;deliveryStatus.Text=sent>0?$"SEND:Gatewayเก็บและACKแล้ว {sent} events • Internet/Telegram:ยังไม่ยืนยัน":"SEND:รอข้อมูลในคิว • ไม่ได้ตรวจInternet";UpdateCounts();await Task.Delay(sent>0?150:1000,token);}catch(OperationCanceledException){throw;}catch(Exception error){failures++;var seconds=Math.Min(30,Math.Pow(2,Math.Min(failures,5)));deliveryStatus.Text=$"SEND:Gateway/TLS/auth/ACKยังไม่สำเร็จ คิวยังอยู่ • ลองใหม่ใน{seconds:0}s • {error.Message}";await Task.Delay(TimeSpan.FromSeconds(seconds),token);}}}
  catch(OperationCanceledException){deliveryStatus.Text="SEND:หยุดแล้ว • คิวที่ไม่ACKยังอยู่";}catch(Exception e){deliveryStatus.Text="SEND:หยุดเพราะผิดพลาด • คิวยังอยู่";Error(e);}finally{sendCts?.Dispose();sendCts=null;Sync();}
 }
 async Task StopSend(){sendCts?.Cancel();if(sendTask is not null)await sendTask;}
 void ShowFrame(ReaderConfig config,ReadFrame frame){values.Rows.Clear();foreach(var o in frame.Observations)values.Rows.Add(o.Tag,o.RawValue?.ToString()??"—",o.State(config.MappingConfirmed) is bool b?(b?"ON":"OFF"):"UNKNOWN",o.Quality(config.MappingConfirmed)+"/"+(o.QualityCode?.ToString()??"—"),"0x"+unchecked((uint)o.ReadError).ToString("X8"),o.SourceTimestamp??"Not reported",frame.ReadAt);}
 void UpdateCounts(){if(spool is not null)counts.Text=$"Snapshots:{spool.Snapshots}   Local pending events:{spool.PendingCount}   Gateway ACKed:{spool.Acked}   Sequence:{spool.Sequence}";}
 void Sync(){var active=readCts is not null||sendCts is not null;foreach(var c in configControls)c.Enabled=!active&&!closing;check.Enabled=!active&&!closing;startRead.Enabled=readCts is null&&!closing;stopRead.Enabled=readCts is not null&&!closing;startSend.Enabled=sendCts is null&&!closing;stopSend.Enabled=sendCts is not null&&!closing;export.Enabled=spool is not null&&!closing;}
 void Error(Exception error){MessageBox.Show(this,error.Message,"AQUA • data retained / no automatic configuration",MessageBoxButtons.OK,MessageBoxIcon.Information);}
 void Export(){try{if(spool is null)return;var folder=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"AquaCommand","WinCCReader","profiles",profile!);using var dialog=new SaveFileDialog{Filter="CSV|*.csv",InitialDirectory=folder,RestoreDirectory=true,FileName="aqua-pending-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+".csv"};if(dialog.ShowDialog(this)==DialogResult.OK)spool.ExportCsv(dialog.FileName);}catch(Exception e){Error(e);}}
 async void OnClosing(object? sender,FormClosingEventArgs e){if(allowClose)return;e.Cancel=true;if(closing)return;closing=true;Sync();await StopRead();await StopSend();spool?.Dispose();secret.Text="";allowClose=true;Close();}
}
